import { provideHttpClient } from '@angular/common/http';
import { provideNgccI18n, HttpNgccI18nLoader } from '@carbideui/components';

bootstrapApplication(AppComponent, {
  providers: [
    provideHttpClient(),
    provideNgccI18n({
      defaultLanguage: 'en',
