        <p class="note">{{ hint() }}</p>
        <div class="code-wrap">
          <button type="button" class="copy cds--btn cds--btn--ghost cds--btn--sm" (click)="copy()">
            {{ copied() ? 'Copied' : 'Copy' }}
          </button>
          <pre class="code" tabindex="0">{{ code() }}</pre>
        </div>
      </section>
    </div>
  `,
  styles: [
    `
